<?php
$pageTitle='Order | Moleqra';require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/commerce.php';$pdo=db();$token=(string)($_GET['token']??'');$order=$pdo&&commerce_schema_ready($pdo)?commerce_order_by_token($pdo,$token):null;if(!$order)http_response_code(404);else$pageTitle=$order['order_number'].' | Moleqra';require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><div class="eyebrow">Order status</div><h1><?= e($order['order_number']??'Order not found') ?></h1><?php if($order):?><p><?= e($order['status']) ?> · Payment <?= e($order['payment_status']) ?> · <?= e($order['fulfilment_status']) ?></p><?php endif;?></div></section><section class="section"><div class="container"><?php if(!$order):?><div class="card">This order link is invalid or unavailable.</div><?php else:?><div class="grid-2"><section class="card"><h2>Items</h2><?php foreach($order['items'] as $i):?><p class="order-line"><span><?= e($i['product_name']) ?> × <?= e((string)$i['quantity']) ?></span><strong><?= e($order['currency']) ?> <?= number_format((float)$i['line_total'],2) ?></strong></p><?php endforeach;?><hr><p class="order-line"><span>Shipping</span><strong><?= e($order['currency']) ?> <?= number_format((float)$order['shipping_total'],2) ?></strong></p><p class="checkout-total"><span>Total</span><strong><?= e($order['currency']) ?> <?= number_format((float)$order['grand_total'],2) ?></strong></p></section><section class="card"><h2>Delivery</h2><p><?= e($order['first_name'].' '.$order['last_name']) ?><br><?= e($order['company']) ?><br><?= e($order['address_line1']) ?><?= $order['address_line2']?'<br>'.e($order['address_line2']):'' ?><br><?= e($order['city'].', '.$order['province'].' '.$order['postal_code']) ?></p><?php if(!empty($order['shipments'])):$sh=$order['shipments'][0];?><p><strong>Shipment</strong><br><?= e($sh['courier']?:'Courier') ?><?= $sh['service']?' · '.e($sh['service']):'' ?><?php if($sh['tracking_number']):?><br>Tracking: <?= e($sh['tracking_number']) ?><?php endif;?></p><?php endif;?><?php if($order['payment_status']==='Pending'):?><a class="btn primary" href="payment/payfast-start.php?token=<?= e($order['order_token']) ?>">Continue payment</a><?php endif;?></section></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
